import{_ as a,o as t,c as r,a2 as o}from"./chunks/framework.CyZTVJbV.js";const u=JSON.parse('{"title":"x.com 投稿用下書き — 日本語 thread (v1.2 milestone voice)","description":"","frontmatter":{},"headers":[],"relativePath":"announcements/v1.2/x-thread-ja.md","filePath":"announcements/v1.2/x-thread-ja.md"}'),i={name:"announcements/v1.2/x-thread-ja.md"};function l(s,e,n,d,c,p){return t(),r("div",null,[...e[0]||(e[0]=[o(`<h1 id="x-com-投稿用下書き-—-日本語-thread-v1-2-milestone-voice" tabindex="-1">x.com 投稿用下書き — 日本語 thread (v1.2 milestone voice) <a class="header-anchor" href="#x-com-投稿用下書き-—-日本語-thread-v1-2-milestone-voice" aria-label="Permalink to &quot;x.com 投稿用下書き — 日本語 thread (v1.2 milestone voice)&quot;">​</a></h1><blockquote><p>投稿先 ... <a href="https://x.com/cardene777" target="_blank" rel="noreferrer">@cardene777</a> Voice ... 本人名義 / 個人 dev 視点 / 「v1.2 完成した」 maker トーン 動画 ... <code>assets/kiwa-promo-ja.mp4</code> (再利用) を 1 ツイート目に添付 想定 ... 1 ツイート 140 字以内 全 8 ツイート、 番号 [1/8] 付き</p></blockquote><hr><h2 id="_1-8-動画添付" tabindex="-1">[1/8] (動画添付) <a class="header-anchor" href="#_1-8-動画添付" aria-label="Permalink to &quot;[1/8] (動画添付)&quot;">​</a></h2><p>polyglot test toolchain 「kiwa」 v1.2 milestone (11/11 resolved) が land しました。</p><p>server-side framework 9 種 + ORM 3 種が「1 spec から並列生成」 の輪に入り、 「test stack 散乱」 を解決する範囲が一段広がりました。</p><p><a href="https://github.com/cardene777/kiwa" target="_blank" rel="noreferrer">https://github.com/cardene777/kiwa</a></p><p>#OSS #testing</p><hr><h2 id="_2-8" tabindex="-1">[2/8] <a class="header-anchor" href="#_2-8" aria-label="Permalink to &quot;[2/8]&quot;">​</a></h2><p>v1.2 で増えたもの。</p><ul><li>npm package ... 11 → 20 (+9)</li><li>Claude Code skill ... 15 → 25 (+10)</li><li>対応 runtime ... Node のみ → Node / Bun / Deno / Edge</li><li>ORM matrix ... 0 → 9 組合せ (Drizzle / Prisma / Kysely × SQLite / Postgres / MySQL)</li></ul><hr><h2 id="_3-8" tabindex="-1">[3/8] <a class="header-anchor" href="#_3-8" aria-label="Permalink to &quot;[3/8]&quot;">​</a></h2><p>server-side framework adapter が 9 種に。</p><p>Next.js / Nuxt / SvelteKit / Remix / Astro / SolidStart / Qwik City / Cloudflare Workers + Vercel Edge / ORM (Drizzle + Prisma + Kysely)。</p><p>全部 <code>setupXxxEnv</code> + <code>mode</code> + <code>stop()</code> 契約を共有しています。</p><hr><h2 id="_4-8" tabindex="-1">[4/8] <a class="header-anchor" href="#_4-8" aria-label="Permalink to &quot;[4/8]&quot;">​</a></h2><p><code>@kiwa-lab/orm</code> v0.6.0 で ORM query test の受入 matrix が 9 組合せに到達しました。</p><p>mock mode (Docker 不要) で速く回し、 live mode (testcontainers) で実 DB に対する query test を deterministic に書ける、 という基本構成です。</p><hr><h2 id="_5-8" tabindex="-1">[5/8] <a class="header-anchor" href="#_5-8" aria-label="Permalink to &quot;[5/8]&quot;">​</a></h2><p>GitHub Issue #525 (5 framework full PoC) も land しました。</p><p><code>examples/{nuxt|sveltekit|remix|astro|nextjs}-full/</code> 配下に real dev server + kiwa helper unit test + Playwright e2e の 2 軸構成で 5 例置いてあります。 retrofit 時の reference にどうぞ。</p><hr><h2 id="_6-8" tabindex="-1">[6/8] <a class="header-anchor" href="#_6-8" aria-label="Permalink to &quot;[6/8]&quot;">​</a></h2><p>CI runtime を 3 系統に拡張しました。</p><ul><li>Node.js 20+</li><li>Bun 1.3+ (<code>bunx --bun vitest run</code>)</li><li>Deno 2.x (<code>deno run --allow-all npm:vitest run</code>)</li></ul><p>全 19 package が 3 runtime で pass する状態を維持しています。</p><hr><h2 id="_7-8" tabindex="-1">[7/8] <a class="header-anchor" href="#_7-8" aria-label="Permalink to &quot;[7/8]&quot;">​</a></h2><p>Claude Code plugin として install すれば dApp 以外の web app でも全 layer 並列生成できます。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/plugin marketplace add cardene777/kiwa</span></span>
<span class="line"><span>/plugin install kiwa@kiwa-marketplace</span></span></code></pre></div><p>25 skill が <code>kiwa:</code> namespace で並びます。</p><hr><h2 id="_8-8" tabindex="-1">[8/8] <a class="header-anchor" href="#_8-8" aria-label="Permalink to &quot;[8/8]&quot;">​</a></h2><p>v1.3 は scope 検討中です。 候補は ORM matrix 補完 (Prisma + MySQL / Kysely Migrator) / 新 layer 追加 (auth / job queue / cache) / 既存 framework 深堀り の 3 系統。</p><p>要望は GitHub Discussions で集めます。 触ってみて感想ください。</p><p><a href="https://github.com/cardene777/kiwa/discussions" target="_blank" rel="noreferrer">https://github.com/cardene777/kiwa/discussions</a></p><p>#testing</p>`,41)])])}const m=a(i,[["render",l]]);export{u as __pageData,m as default};
